INSERT INTO `pages` VALUES (1,'home.index','Homepage - Tero','Terodesign studio. 3D visualization service. Portfolio','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, service',''),(2,'services.index','Services - Tero','Terodesign studio. Services. What we do?','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, animation, service, portfolio, development',''),(3,'workflow.index','Workflow - Tero','Terodesign studio. Workflow. How we work?','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, workflow',''),(4,'team.index','Team - Tero','Terodesign studio. Our team.','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, team','{\"title\":\"Meet us\",\"text\":\"<p>We are Terodesign - an architectural visualization studio with many years of experience, hundreds of happy clients, and thousands of created visualizations. We have created commercial and non-commercial visualization for projects around the world and we are very proud of that. We try not only to fulfill all the wishes of the client when working on a project but also to put a piece of our soul into every picture we make. And we truly hope that this can be seen in all our visualizations.</p>\"}'),(5,'contact.index','Contact - Tero','Terodesign studio. Contact. Get in touch. Chat','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, contact',''),(6,'price.index','Price - Tero','Terodesign studio. Price.','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, contact',NULL);
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
UNLOCK TABLES;

