INSERT INTO `tbl_pages` VALUES (1,'index','Homepage - Tero','Terodesign studio. 3D visualization service. Portfolio','3D,visualization,terodesign,studio,exterior,archviz,archvis,interior,cgi,render,rendering,design,cgartist,architecture,designer,concept,realestate,estate,service,portfolio,service',''),(2,'services','Services - Tero','Terodesign studio. Services. What we do?','3D,visualization,terodesign,studio,exterior,archviz,archvis,interior,cgi,render,rendering,design,cgartist,architecture,designer,concept,realestate,animation,service,portfolio,development',''),(3,'workflow','Workflow - Tero','Terodesign studio. Workflow. How we work?','3D,visualization,terodesign,studio,exterior,archviz,archvis,interior,cgi,render,rendering,design,cgartist,architecture,designer,concept,realestate,estate,service,portfolio,workflow',''),(4,'team','Team - Tero','Terodesign studio. Our team.','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, team','<p>We are Terodesign - an architectural visualization studio with many years of experience, hundreds of happy clients, and thousands of created visualizations. We have created commercial and non-commercial visualization for projects around the world and we are very proud of that. We try not only to fulfill all the wishes of the client when working on a project but also to put a piece of our soul into every picture we make. And we truly hope that this can be seen in all our visualizations.</p>'),(5,'contact','Contact - Tero','Terodesign studio. Contact. Get in touch. Chat','3D, visualization, terodesign, studio, exterior, archviz, archvis, interior, cgi, render, rendering, design, cgartist, architecture, designer, concept, realestate, estate, service, portfolio, contact','');
